"""Generate additive grounded knowledge schemas and BigQuery migration 004."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from scripts.export_knowledge_contract import bq_type
from src.models.knowledge_base import KB_KEYS, KB_MODELS


def artifacts():
    output = {}
    sql = [
        "-- Generated by scripts/export_knowledge_base.py; additive phase 7, no embedding/vector tables.",
        "-- Apply 001/002/003 first with workers stopped. Revisions preserve contract-v1 sources/evidence.",
    ]
    for table, model in KB_MODELS.items():
        schema = model.model_json_schema()
        output[ROOT / "schemas/knowledge-base-v1" / f"{table}.schema.json"] = (
            json.dumps(schema, ensure_ascii=False, indent=2) + "\n"
        )
        columns = []
        for name, node in schema["properties"].items():
            kind, nullable = bq_type(node, schema.get("$defs", {}))
            required = "" if nullable or kind.startswith("ARRAY<") else " NOT NULL"
            columns.append(f"  `{name}` {kind}{required}")
        sql.append(
            f"\nCREATE TABLE IF NOT EXISTS `${{PROJECT_ID}}.${{DATASET}}.{table}` (\n"
            + ",\n".join(columns)
            + f"\n)\nCLUSTER BY {KB_KEYS[table]};"
        )
    output[ROOT / "sql/migrations/004_grounded_knowledge.sql"] = "\n".join(sql) + "\n"
    return output


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for path, content in artifacts().items():
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                raise SystemExit(f"Outdated artifact: {path}")
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
    print(
        "Knowledge base schemas verified"
        if args.check
        else "Knowledge base schemas exported"
    )


if __name__ == "__main__":
    main()
